import{_ as a,c as o,o as t,ae as r}from"./chunks/framework.iOmxR4Tm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"keep4o/index.md","filePath":"keep4o/index.md"}'),i={name:"keep4o/index.md"};function l(p,e,s,n,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="keep4o" tabindex="-1">Keep4o <a class="header-anchor" href="#keep4o" aria-label="Permalink to &quot;Keep4o&quot;">​</a></h2><p>Keep4o 是一条面向「GPT-4o 风格对齐」的数据流水线：用你自己的 ChatGPT 导出数据，抽取出可训练的 SFT（先做纯文本风格闭环），再用 OpenAI-compatible 的 API 进行二次清洗，最后进入微调/蒸馏。</p><p>这条路线的目标是<strong>对齐“输出结构、澄清方式、拒答习惯、表达语气、工具调用倾向”</strong>，而不是做“数字分身”。如果你要训练个人化风格，请走「快速上手」里的 QQ/TG 流程。</p><hr><h2 id="为什么要-keep4o" tabindex="-1">为什么要 Keep4o <a class="header-anchor" href="#为什么要-keep4o" aria-label="Permalink to &quot;为什么要 Keep4o&quot;">​</a></h2><p>很多人喜欢 4o 的表达方式和“对话质感”。Keep4o 希望通过蒸馏与对齐，让这种风格在本地模型上以可复现的方式延续下去（但不追求逐 token 复刻，也不推断任何隐藏 system prompt）。</p><hr><h2 id="你会得到什么" tabindex="-1">你会得到什么 <a class="header-anchor" href="#你会得到什么" aria-label="Permalink to &quot;你会得到什么&quot;">​</a></h2><ul><li><code>runs/openai-distill/&lt;run_id&gt;/sft/text.jsonl</code>：从 ChatGPT 导出中抽取出来的纯文本 SFT（默认只保留 <code>gpt-4o,gpt-4-1</code>）</li><li><code>runs/openai-clean/&lt;run_id&gt;/sft/train.jsonl</code>：LLM 清洗后的可训练数据（去技术/工具/搜索痕迹，注入可选的 4o 风格 system prompt）</li></ul><hr><h2 id="隐私与安全" tabindex="-1">隐私与安全 <a class="header-anchor" href="#隐私与安全" aria-label="Permalink to &quot;隐私与安全&quot;">​</a></h2><ul><li>ChatGPT 导出数据属于强隐私；请放在 <code>data/openai-export/</code>，不要提交到 git</li><li>默认只保留训练需要的字段；建议开启 PII 策略（默认 <code>mask</code>）</li></ul><hr><h2 id="贡献数据-可选" tabindex="-1">贡献数据（可选） <a class="header-anchor" href="#贡献数据-可选" aria-label="Permalink to &quot;贡献数据（可选）&quot;">​</a></h2><p>如果你愿意帮 Keep4o 的数据更丰富（尤其是高质量长对话、复杂澄清、稳定拒答、结构化输出等），可以把你从 ChatGPT 导出的压缩包（或解压后的 <code>conversations.json</code>）发给我：</p><ul><li>X：<a href="https://x.com/qqqqqf5" target="_blank" rel="noreferrer">@qqqqqf5</a></li><li>Telegram：<a href="https://t.me/NS_qingf_bot" target="_blank" rel="noreferrer">点击此处添加我的双向聊天</a></li></ul><p>我们需要更多数据与更多 GPU 来 Keep4o。</p><hr><h2 id="当前效果-示例" tabindex="-1">当前效果（示例） <a class="header-anchor" href="#当前效果-示例" aria-label="Permalink to &quot;当前效果（示例）&quot;">​</a></h2><p>以下是使用 <code>Qwen2.5 1.5B Instruct</code> + 我自己的数据训练的 LoRA + 仿 4o system prompt 的部分输出示例：</p><h3 id="_4o-lora-仿-4o-system-prompt" tabindex="-1">4o LoRA + 仿 4o System Prompt <a class="header-anchor" href="#_4o-lora-仿-4o-system-prompt" aria-label="Permalink to &quot;4o LoRA + 仿 4o System Prompt&quot;">​</a></h3><p><img src="https://cdn.nodeimage.com/i/9SmHj5O98XQQW3UwuSdUYDOsSQjouGBv.webp" alt="4o lora + system prompt"></p><h3 id="同上-第二次输出" tabindex="-1">同上（第二次输出） <a class="header-anchor" href="#同上-第二次输出" aria-label="Permalink to &quot;同上（第二次输出）&quot;">​</a></h3><p><img src="https://cdn.nodeimage.com/i/S4kxv76frlii26zlX4tmdXXlq1xINXDe.webp" alt="second output"></p><h3 id="仅仿-4o-system-prompt" tabindex="-1">仅仿 4o System Prompt <a class="header-anchor" href="#仅仿-4o-system-prompt" aria-label="Permalink to &quot;仅仿 4o System Prompt&quot;">​</a></h3><p><img src="https://cdn.nodeimage.com/i/RRyJRANLgP6v1W2AINNy5uXyz8B4ghb4.webp" alt="system prompt only"></p><h3 id="仅-qwen-原模型-无-system-prompt" tabindex="-1">仅 Qwen 原模型（无 System Prompt） <a class="header-anchor" href="#仅-qwen-原模型-无-system-prompt" aria-label="Permalink to &quot;仅 Qwen 原模型（无 System Prompt）&quot;">​</a></h3><p><img src="https://cdn.nodeimage.com/i/OxgLDX78G6ADAZdubwmXP4MUQzQTdS9P.webp" alt="base model"></p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>按左侧导航从「导出 ChatGPT 数据」开始走一遍即可。</p>',31)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
